function fuzzyMatch(query, str){
  var q=String(query||'').toLowerCase(), s=String(str||''), sl=s.toLowerCase();
  if(!q) return { matched:true, score:0, positions:[] };
  var positions=[], score=0, si=0, prev=-2;
  for(var qi=0;qi<q.length;qi++){
    var found=-1;
    for(var i=si;i<sl.length;i++){ if(sl[i]===q[qi]){ found=i; break; } }
    if(found<0) return { matched:false, score:0, positions:[] };
    var pts=1;
    if(found===prev+1) pts+=4;
    if(found===0) pts+=6;
    else {
      var c=s[found-1];
      if(c==='/'||c==='\\'||c==='-'||c==='_'||c==='.'||c===' ') pts+=5;
      else if(c===c.toLowerCase() && s[found]!==s[found].toLowerCase()) pts+=4;
    }
    score+=pts;
    positions.push(found);
    prev=found; si=found+1;
  }
  score -= Math.floor((positions[positions.length-1]-positions[0]-q.length+1)/3);
  score -= Math.floor(positions[0]/4);
  return { matched:true, score:score, positions:positions };
}
function fuzzyFilter(query, list){
  var out=[];
  for(var i=0;i<list.length;i++){
    var r=fuzzyMatch(query, list[i]);
    if(r.matched) out.push({ item:list[i], score:r.score, positions:r.positions });
  }
  out.sort(function(a,b){ return b.score-a.score || a.item.length-b.item.length; });
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { fuzzyMatch:fuzzyMatch, fuzzyFilter:fuzzyFilter };
}
if (typeof window !== 'undefined') {
  window.FuzzyForgePure = { fuzzyMatch:fuzzyMatch, fuzzyFilter:fuzzyFilter };
}
